def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 3]
    for r, c in points:
        left, right = c - 2, c + 2
        top, bottom = r - 2, r + 2
        for x in range(left, right + 1):
            if 0 <= x < w and 0 <= top < h:
                out[top][x] = 5
        if 0 <= top < h and 0 <= c < w:
            out[top][c] = 5
        for y in range(top + 1, bottom):
            if 0 <= y < h:
                if 0 <= left < w:
                    out[y][left] = 2
                if 0 <= right < w:
                    out[y][right] = 2
        if 0 <= bottom < h:
            for x in range(w):
                out[bottom][x] = 2
            for x in range(left, right + 1):
                if 0 <= x < w:
                    out[bottom][x] = 8
        out[r][c] = 3
    return out

